    if set(report.keys()) != _PA_REPORT_KEYS:
        raise invalid(
            f"{where} report must contain exactly the keys 'error', 'id', "
            "'result' and 'status'"
        )
    report_id = report[ID]
    if not isinstance(report_id, str):
        raise TypeError(f"{where} report id must be a str")
    if report_id == "":
        raise invalid(
            f"{where} report id must be a non-empty str"
        )
    if report_id != expected_id:
        raise invalid(
            f"{where} report id does not match the item id"
        )
    status = report[STATUS]
    if not isinstance(status, str):
        raise TypeError(f"{where} report status must be a str")
    if status not in _PADB_VERIFY_STATUSES:
        raise invalid(
            f"{where} report status is not a known status"
        )
    error = report[PRUNE_ERROR]
    raw_result = report[VERDICT_ITEM_RESULT]
    if status == _VERIFY_VERIFIED:
        if error is not None:
            raise invalid(
                f"{where} report error must be null when verified"
            )
        try:
            validated_result = _validated_prune_adjudication_payload(
                raw_result
            )
        except InvalidPruneAdjudicationError as exc:
            # An embedded key-set, version, digest, ordering, row or
            # report-shape fault is a fault of this packet's content; a
            # wrong JSON field type is a TypeError and propagates as one.
            raise invalid(str(exc)) from exc
    else:
        if not isinstance(error, str):
            raise TypeError(f"{where} report error must be a str for a failure")
        if error == "":
            raise invalid(
                f"{where} report error must be a non-empty str for a failure"
            )
        if raw_result is not None:
            raise invalid(
                f"{where} report result must be null for a failure"
            )
        validated_result = None
    return {
        PRUNE_ERROR: error,
        ID: report_id,
        VERDICT_ITEM_RESULT: validated_result,
        STATUS: status,
    }


def _validated_signed_batch_items(
    items: object, invalid, what: str
) -> list[dict]:
    """Validate the original-order item list of a signed batch handover.

    Each item carries exactly ``id``, ``digest`` and the full batch
    verification ``report``.  ``invalid`` builds the packet-specific
    structural error.  A field of the wrong JSON type raises
    :class:`TypeError` (a :class:`bool` never poses as an int); every
    key-set, value, digest, id or report-shape fault raises the error
    ``invalid`` builds.
    """
    if not isinstance(items, list):
        raise TypeError(f"{what} items must be a list")
    if not items:
        raise invalid(f"{what} items must be a non-empty list")
    seen_ids: set[str] = set()
    normalized_items: list[dict] = []
    for position, item in enumerate(items):
        where = f"{what} item {position}"
        if not isinstance(item, dict):
            raise TypeError(f"{where} must be an object")
        if set(item.keys()) != _PADB_ITEM_KEYS:
            raise invalid(
                f"{where} must contain exactly the keys 'id', 'digest' and "
                "'report'"
            )
        item_id = item[ID]
        if not isinstance(item_id, str):
            raise TypeError(f"{where} id must be a str")
        if item_id == "":
            raise invalid(f"{where} id must be a non-empty str")
        if item_id in seen_ids:
            raise invalid(f"{what} item ids must be unique")
        seen_ids.add(item_id)
        digest = item[CP_DIGEST]
        if not _prune_is_digest(digest):
            raise invalid(
                f"{where} digest must be 64 lowercase hex characters"
            )
        report = _validated_prune_adjudications_report(
            item[RECEIPT_ITEM_REPORT], item_id, where, invalid=invalid
        )
        normalized_items.append({
            ID: item_id,
            CP_DIGEST: digest,
            RECEIPT_ITEM_REPORT: report,
        })
    return normalized_items


def _validated_signed_batch_payload(
    payload: object, invalid, what: str
) -> dict:
    """Validate the shared signed-batch payload shape into a fresh copy.

    The shape is the one :func:`sign_prune_adjudication_batch` and
    :func:`aggregate_prune_batches` bind: ``issuer``, ``keyVersion``,
    ``moment``, ``policyDigest``, ``items`` and ``version`` (the integer
    1), with one item per verified-or-failed handover in the original
    order carrying exactly ``id``, ``digest`` and the full batch
    verification ``report``.  ``what`` names the packet for error text
    and ``invalid`` builds the packet-specific structural error.

    A field of the wrong JSON type raises :class:`TypeError` (a
    :class:`bool` never poses as an int); every key-set, value, digest,
    id, report-shape or canonical-content fault raises the error
    ``invalid`` builds.
    """
    if not isinstance(payload, dict):
        raise TypeError(f"{what} payload must be an object")
    if set(payload.keys()) != _PADB_PAYLOAD_KEYS:
        raise invalid(
            f"{what} payload must contain exactly the keys 'issuer', "
            "'keyVersion', 'moment', 'policyDigest', 'items' and 'version'"
        )
    issuer = payload[VD_ISSUER]
    if not isinstance(issuer, str):
        raise TypeError(f"{what} payload issuer must be a str")
    if issuer == "":
        raise invalid(f"{what} payload issuer must be a non-empty str")
    key_version = payload[KEY_VERSION]
    if isinstance(key_version, bool) or not isinstance(key_version, int):
        raise TypeError(f"{what} payload keyVersion must be an int")
    if key_version <= 0:
        raise invalid(f"{what} payload keyVersion must be positive")
    moment = payload[CP_MOMENT]
    if isinstance(moment, bool) or not isinstance(moment, int):
        raise TypeError(f"{what} payload moment must be an int")
    if moment < 0:
        raise invalid(f"{what} payload moment must be non-negative")
    if not _prune_is_digest(payload[VD_POLICY_DIGEST]):
        raise invalid(
            f"{what} policyDigest must be 64 lowercase hex characters"
        )
    version = payload[VERSION]
    if isinstance(version, bool) or not isinstance(version, int):
        raise TypeError(f"{what} payload version must be an int")
    if version != PRUNE_ADJUDICATION_BATCH_VERSION:
        raise invalid(f"{what} payload version must be the integer 1")

    normalized_items = _validated_signed_batch_items(
        payload[PA_ITEMS], invalid, what
    )

    return {
        VD_ISSUER: issuer,
        KEY_VERSION: key_version,
        CP_MOMENT: moment,
        VD_POLICY_DIGEST: payload[VD_POLICY_DIGEST],
        PA_ITEMS: normalized_items,
        VERSION: PRUNE_ADJUDICATION_BATCH_VERSION,
    }


def _parse_prune_adjudication_batch(raw: object) -> tuple[dict, str]:
    """Validate batch packet bytes structurally into ``(payload, signature)``.

    A non-bytes argument or a public field of the wrong type raises
    :class:`TypeError` (a :class:`bool` never poses as an int); every
    encoding, key-set, version, digest, report-shape or canonical-form
    fault raises :class:`InvalidPruneAdjudicationBatchError`.  The
    policy, moment, credential and signature bindings are checked by
    :func:`verify_prune_adjudication_batch`.
    """
    if not isinstance(raw, bytes):
        raise TypeError("batch packet must be bytes")
    if not raw or raw[-1:] in (b"\n", b"\r", b" ", b"\t"):
        raise _prune_adjudication_batch_invalid(
            "batch packet must end with the closing brace, no trailing byte"
        )
    try:
        text = raw.decode("utf-8")
    except UnicodeDecodeError as exc:
        raise _prune_adjudication_batch_invalid(
            "batch packet is not valid UTF-8"
        ) from exc
    try:
        data = json.loads(
            text,
            object_pairs_hook=_reject_duplicate_prune_batch_keys,
        )
    except json.JSONDecodeError as exc:
        raise _prune_adjudication_batch_invalid(
            "batch packet is not valid JSON"
        ) from exc

    if not isinstance(data, dict):
        raise TypeError("batch packet must be a JSON object")
    if set(data.keys()) != _PA_PACKET_KEYS:
        raise _prune_adjudication_batch_invalid(
            "batch packet must contain exactly the keys 'payload' and "
            "'signature'"
        )
    signature = data[SIGNATURE]
    if not isinstance(signature, str):
        raise TypeError("batch packet signature must be a str")
    if _PRUNE_HEX64.fullmatch(signature) is None:
        raise _prune_adjudication_batch_invalid(
            "batch packet signature must be 64 lowercase hex characters"
        )

    normalized_payload = _validated_signed_batch_payload(
        data[TICKET_PAYLOAD], _prune_adjudication_batch_invalid, "batch packet"
    )
    if _prune_compact({TICKET_PAYLOAD: normalized_payload,
                       SIGNATURE: signature}) != raw:
        raise _prune_adjudication_batch_invalid(
            "batch packet encoding is not the canonical compact form"
        )
    return normalized_payload, signature


def sign_prune_adjudication_batch(
    items, policy, keyring, moment, issuer, version
):
    """Sign one batch of prune adjudication verifications for handover.

    ``items`` is the same non-empty list of ``{"id", "adjudication"}``
    dicts :func:`verify_prune_adjudications` takes; ``policy`` is the
    same ``{"batch", "sites", "threshold"}`` object, ``keyring`` follows
    the :func:`apply_signed_remote` rules, ``moment`` is the verification
    time and ``issuer``/``version`` name the exact signing credentials.
    No file is read or written and no argument is modified.

    The batch runs through the exact :func:`verify_prune_adjudications`
    rules: batch-level faults raise directly (container, element or
    public field type faults raise :class:`TypeError` -- a :class:`bool`
    never poses as an int -- and an empty list, an empty or duplicate
    id, a wrong item key set, an empty issuer or a non-positive version

def _fe_moment(value: object, name: str) -> int:
    """Validate a public non-negative, non-bool moment argument."""
    if isinstance(value, bool) or not isinstance(value, int):
        raise TypeError(f"{name} must be an int")
    if value < 0:
        raise ValueError(f"{name} must be non-negative")
    return value


def _validated_fe_boundary(value: object, where: str) -> dict:
    """Validate one fork boundary inside an execution plan.

    Same shape as :func:`_validated_boundary_object`, but every
    non-type fault raises :class:`InvalidForkExecutionError` rather than
    the fork-decision error, since the boundary is bound inside a plan.
    """
    if not isinstance(value, dict):
        raise TypeError(f"{where} boundary must be an object")
    if set(value.keys()) != _FD_BOUNDARY_KEYS:
        raise _fork_execution_invalid(
            f"{where} boundary must contain exactly the keys 'receiptDigest', "
            "'target' and 'upstream'"
        )
    receipt_digest = value[DELEGATION_RECEIPT_DIGEST]
    upstream = value[DELEGATION_UPSTREAM]
    target = value[DELEGATION_TARGET]
    if not isinstance(receipt_digest, str):
        raise TypeError(f"{where} receiptDigest must be a str")
    if not isinstance(upstream, str):
        raise TypeError(f"{where} upstream must be a str")

def _usable_checkpoint_key(
    keyring: dict[str, list[dict]],
    issuer: str,
    key_version: int,
    moment: int,
) -> dict:
    """Select the exact key and require it to be usable at ``moment``.

    Unknown credentials and a revoked, not-yet-valid or expired key
    raise :class:`AuthenticationError`; selection never falls back to
    another version.
    """
    entry = _select_checkpoint_key(keyring, issuer, key_version)
    if entry[REVOKED]:
        raise AuthenticationError(
            f"credentials for issuer {issuer!r} key version {key_version} "
            "are revoked"
        )
    if moment < entry[NOT_BEFORE]:
        raise AuthenticationError(
            f"credentials for issuer {issuer!r} key version {key_version} "
            "are not yet valid"
        )
    if moment > entry[NOT_AFTER]:
        raise AuthenticationError(
            f"credentials for issuer {issuer!r} key version {key_version} "
            "have expired"
        )
    return entry


def _checkpoint_payload_bytes(payload: dict) -> bytes:
    """The signed canonical bytes: the payload alone, compact and sorted."""
    return _checkpoint_compact(payload)


def _parse_checkpoint(raw: object) -> tuple[dict, str]:
    """Validate checkpoint bytes structurally into ``(payload, signature)``.

    A non-bytes argument or a field of the wrong type raises
    :class:`TypeError` (a :class:`bool` never poses as an int); every
    encoding, key-set, range, shape or canonical-format fault raises
    :class:`InvalidRecoveryCheckpointError`.
    """
    if not isinstance(raw, bytes):
        raise TypeError("checkpoint must be bytes")
    # The checkpoint carries no terminator of any kind: no trailing
    # newline and no other byte past the closing brace.
    if not raw or raw[-1:] in (b"\n", b"\r", b" ", b"\t"):
        raise _checkpoint_invalid("must end with the closing brace, no LF")
    try:
        text = raw.decode("utf-8")
    except UnicodeDecodeError as exc:
        raise _checkpoint_invalid("is not valid UTF-8") from exc
    try:
        # The pairs hook raises directly on duplicate object keys.
        data = json.loads(text, object_pairs_hook=_reject_duplicate_checkpoint_keys)
